import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.CfwCq2QB.js";const d="/dev-go-docs/shots/0.2.3/zh-CN/light/newtab.png",u=JSON.parse('{"title":"新标签页","description":"","frontmatter":{},"headers":[],"relativePath":"features/newtab.md","filePath":"features/newtab.md"}'),n={name:"features/newtab.md"};function s(l,t,i,c,h,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="新标签页" tabindex="-1">新标签页 <a class="header-anchor" href="#新标签页" aria-label="Permalink to &quot;新标签页&quot;">​</a></h1><p>一句话：搜索引擎切换 + bang 语法（如 <code>!gh</code>）、聚合导航与书签的搜索联想、快捷导航分类管理与多种动态背景。</p><h2 id="搜索-引擎切换与-bang-语法" tabindex="-1">搜索：引擎切换与 bang 语法 <a class="header-anchor" href="#搜索-引擎切换与-bang-语法" aria-label="Permalink to &quot;搜索：引擎切换与 bang 语法&quot;">​</a></h2><p>输入框默认用当前搜索引擎搜索，输入 <code>!bang 词</code> 可以<strong>临时</strong>切换引擎搜这一次，不用先改设置：</p><table tabindex="0"><thead><tr><th>输入</th><th>实际用哪里搜</th></tr></thead><tbody><tr><td><code>!gh react</code></td><td>GitHub</td></tr><tr><td><code>!npm vite</code></td><td>npm</td></tr><tr><td><code>!mdn fetch</code></td><td>MDN</td></tr><tr><td><code>!so cors error</code></td><td>Stack Overflow</td></tr><tr><td><code>!g 关键词</code> / <code>!bd 关键词</code> / <code>!b 关键词</code></td><td>Google / 百度 / Bing</td></tr></tbody></table><p>输入的同时会聚合<strong>导航和浏览器书签</strong>的联想结果，常用站点不用进收藏夹。</p><h2 id="快捷导航" tabindex="-1">快捷导航 <a class="header-anchor" href="#快捷导航" aria-label="Permalink to &quot;快捷导航&quot;">​</a></h2><ul><li>预置 <strong>常用 / 开发 / AI / 社区 / 工具</strong> 五个分类，双击分类名可重命名</li><li>悬停任意站点卡片：编辑、删除、<strong>固定到搜索框下方</strong>（固定栏有上限，满了会提示）</li><li>添加站点时填名称、网址、选分类即可</li></ul><p>导航配置支持<strong>导入 / 导出</strong> JSON：换机、多设备统一布局都靠它；重复的条目导入时自动跳过。新安装用户的默认导航会随版本修订（比如失效链接会被移除），你手动改过的条目永远不会被覆盖。</p><h2 id="背景与主题" tabindex="-1">背景与主题 <a class="header-anchor" href="#背景与主题" aria-label="Permalink to &quot;背景与主题&quot;">​</a></h2><ul><li><strong>动态背景</strong>：流体、神经、柔波、烟环、熔球等 12 种着色器效果，可设「随机」（每次换一个）或「固定」</li><li><strong>颜色主题</strong>：浅色 / 深色 / 自动，自动指 18:00 – 6:00 用深色；与弹窗、设置页、侧边栏统一生效</li></ul><img src="'+d+'" alt="新标签页"><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>快捷导航和代理配置参与<a href="/dev-go-docs/settings/sync.html">跨设备同步</a>：登录同一浏览器账号自动带到其他设备；同步空间有上限（Chrome 为 100KB），导航特别多时可能提示删减</li></ul>',14)])])}const p=e(n,[["render",s]]);export{u as __pageData,p as default};
